for chapter,pairs in edits.items():
    rel='05-language-models/01-foundations/'+chapter+'.md'
    def op(s):
        for before,after in pairs:
            assert before in s,before
            s=s.replace(before,after)
        return s
    transform(rel,op,'Пакет из десяти карточек: исходные случаи прочитаны, восстановлены границы утверждений о порядке, различия состояний и параметров и полный выходной путь.',c);save(c)
    parts=sections((ROOT/rel).read_text(encoding='utf8'))
    dest={ident:[title]+extras.get(ident,[]) for title,ids in groups[chapter].items() for ident in ids.split()}
    units=[u for u in c['units'] if u.get('chapter')==chapter and not u.get('provenance_only')]
    assert set(dest)=={u['id'] for u in units}
    for u in units:
        targets=[]
        for j,title in enumerate(dest[u['id']]):
            a,b,body=parts[title];key=u['anchor'] if j==0 else f"t-batch1-{u['id']}-{j}"
            c['spans'][key]={'path':rel,'start_line':a,'end_line':b,'sha256':digest(body),'destination_section':title,'status':'revised','review_status':'pending','rationale':'Индивидуальная исходная единица сопоставлена после чтения; повторные объяснения объединены, составные случаи имеют дополнительные назначения.'}
            targets.append(key)
        u.update(targets=targets,status='semantic-review-pending',action='объединить с сохранением нюансов')
    save(c)
